    add(table(['Partition','Fixed condition','Condition true','A1 true','Both','Condition without A1','A1 without condition','Target0 condition'],[[p,k]+[v[n] for n in ('condition_true','A1_true','both','condition_without_A1','A1_without_condition','target0_condition')] for p,part in eligibility.items() for k,v in part['A1_component_contingencies'].items()]))
    add('In Validation, available growth≥1.5 covers 2,648 A1 positives, with 177 non-A1 rows (117 target0), while 97 A1 positives are unavailable. Growth contains only the relative-growth component: it does not encode the novelty/count conjunction, other families, or complete target. Therefore a direct complete-oracle claim is false, while an A1 near-proxy concern is well supported. Strong target alignment from permitted observables is distinct from private-field or future leakage.\n')
